  device_id_hash: string;  // SHA-256 hash of device identifier
  batch_id: string;        // Identifies the aggregation window
  share: number;          // Encrypted score contribution
  timestamp: number;      // Unix timestamp from device
  signature: string;      // Device-signed payload
};

